public sealed interface PaymentResult
        permits PaymentResult.Success, PaymentResult.Declined, PaymentResult.Error {
    record Success(String transactionId, BigDecimal amount) implements PaymentResult {}
    record Declined(String reason) implements PaymentResult {}
    record Error(Exception cause) implements PaymentResult {}
}

public static String describe(PaymentResult result) {
    return switch (result) {
        case PaymentResult.Success s -> "Paid: " + s.transactionId();
        case PaymentResult.Declined d -> "Declined: " + d.reason();
        case PaymentResult.Error e -> "Error: " + e.cause().getMessage();
    };
}

pattern.example:
public record UserId(String value) {
    public UserId {
        Objects.requireNonNull(value, "UserId must not be null");
        if (value.isBlank()) throw new IllegalArgumentException("UserId must not be blank");
    }
}

public record CreateUserCommand(String email, String name) {
    public CreateUserCommand {
        Objects.requireNonNull(email, "email required");
        Objects.requireNonNull(name, "name required");
        if (name.isBlank()) throw new IllegalArgumentException("name must not be blank");
    }
}

public sealed interface Shape permits Shape.Circle, Shape.Rectangle, Shape.Triangle {
    record Circle(double radius) implements Shape {}
    record Rectangle(double width, double height) implements Shape {}
    record Triangle(double base, double height) implements Shape {}
}

public static double area(Shape shape) {
    return switch (shape) {
        case Shape.Circle c -> Math.PI * c.radius() * c.radius();
        case Shape.Rectangle r -> r.width() * r.height();
        case Shape.Triangle t -> 0.5 * t.base() * t.height();
    };
}

